def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Scattered marker cells are isolated foreground pixels. Identify their color.
    isolated = Counter()
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v == bg:
                continue
            if all(
                not (0 <= nr < h and 0 <= nc < w and grid[nr][nc] != bg)
                for nr, nc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1))
            ):
                isolated[v] += 1
    marker = isolated.most_common(1)[0][0]

    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    cells = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] != bg and grid[r][c] != marker]
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    pattern = [[grid[r][c] for c in range(c0, c1 + 1)] for r in range(r0, r1 + 1)]

    out = [row[:] for row in grid]
    ar, ac = (r1 - r0) // 2, (c1 - c0) // 2
    for mr, mc in markers:
        for i, row in enumerate(pattern):
            for j, value in enumerate(row):
                rr, cc = mr + i - ar, mc + j - ac
                if value != bg and 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = value
    return out
